pat = re.compile(r'([A-Za-z0-9+#./ _-]+?)\s*\(([\d,]+)\s*bytes\)')

def main_lang(desc):
    matches = pat.findall(str(desc))
    if not matches:
        return None
    parsed = [(name.strip(), int(b.replace(',', ''))) for name, b in matches]
    parsed.sort(key=lambda x: -x[1])
    return parsed[0][0]

